mapper.select:
SELECT pr.user_id userId,uu.`name`, uo.org_name department, td.`name` position, pr.fee_type feeType, pr.reimburse_amount reimburseAmount, DATE_FORMAT(pt.start_time,'%Y年%c月%e日') carUseDate, pt.`start`, pt.destination, pr.invoice, pr.approval_status approvalStatus, pr.reimburse_id reimburseId, pr.create_time createTime FROM pubcar_reimburse pr LEFT JOIN pubcar_trip pt ON pt.trip_id = pr.trip_id AND pt.status_cd = '0' LEFT JOIN u_user uu ON uu.user_id = pr.user_id AND uu.status_cd = '0' LEFT JOIN u_org_staff_rel uosr ON uosr.staff_id = uu.user_id AND uosr.status_cd = '0' LEFT JOIN u_org uo ON uo.org_id = uosr.org_id AND uo.status_cd = '0' LEFT JOIN t_dict td ON td.status_cd = uosr.rel_cd AND td.table_name = 'u_org_staff_rel' AND td.table_columns = 'rel_cd' WHERE pr.status_cd = '0' AND pr.reimburse_id IN ( SELECT temp.id FROM( SELECT pr.reimburse_id id FROM pubcar_reimburse pr LEFT JOIN pubcar_trip pt ON pt.trip_id = pr.trip_id AND pt.status_cd = '0' LEFT JOIN u_user uu ON uu.user_id = pr.user_id AND uu.status_cd = '0' LEFT JOIN u_org_staff_rel uosr ON uosr.staff_id = uu.user_id AND uosr.status_cd = '0' LEFT JOIN u_org uo ON uo.org_id = uosr.org_id AND uo.status_cd = '0' LEFT JOIN t_dict td ON td.status_cd = uosr.rel_cd AND td.table_name = 'u_org_staff_rel' AND td.table_columns = 'rel_cd' WHERE pr.status_cd = '0'
AND pt.start_time >= #{lessCarUseDate}
AND pt.start_time <= #{moreCarUseDate}
AND uo.org_name LIKE concat('%',#{department},'%')
AND td.`name` LIKE concat('%',#{position},'%')
AND uu.`name` LIKE concat('%',#{name},'%')
ORDER BY pr.create_time DESC
LIMIT #{page}, #{row}
) as temp )

SELECT COUNT(DISTINCT pr.user_id) count FROM pubcar_reimburse pr LEFT JOIN pubcar_trip pt ON pt.trip_id = pr.trip_id AND pt.status_cd = '0' LEFT JOIN u_user uu ON uu.user_id = pr.user_id AND uu.status_cd = '0' LEFT JOIN u_org_staff_rel uosr ON uosr.staff_id = uu.user_id AND uosr.status_cd = '0' LEFT JOIN u_org uo ON uo.org_id = uosr.org_id AND uo.status_cd = '0' LEFT JOIN t_dict td ON td.status_cd = uosr.rel_cd AND td.table_name = 'u_org_staff_rel' AND td.table_columns = 'rel_cd' WHERE pr.status_cd = '0'
AND pt.start_time >= #{lessCarUseDate}
AND pt.start_time <= #{moreCarUseDate}
AND uo.org_name LIKE concat('%',#{department},'%')
AND td.`name` LIKE concat('%',#{position},'%')
AND uu.`name` LIKE concat('%',#{name},'%')
